{
  "name": "Author",
  "path": "/authors",
  "table": "author",
  "itemsPerPage": 2,
  "properties": {
    "id": {"type": "integer", "identifier": true, "readOnly": true},
    "name": {"type": "string", "required": true}
  }
}
EOF
cat > resources/Book.json <<'EOF'
{
  "name": "Book",
  "path": "/books",
  "query": "book.query.ts",
  "command": "book.command.ts",
  "itemsPerPage": 2,
  "input": {
    "title": {"type": "string", "required": true},
    "author_id": {"type": "integer", "required": true},
    "published": {"type": "boolean"}
  },
  "properties": {
    "id": {"type": "integer", "identifier": true},
    "title": {"type": "string"},
    "author": {"type": "string", "filterable": true},
    "published": {"type": "boolean"}
  }
}
EOF
cat > resources/book.query.ts <<'EOF'
export default function query(ctx: QueryContext): Sql {
  return ctx.sql`
    SELECT b.id, b.title, a.name AS author, b.published
    FROM book b
    LEFT JOIN author a ON a.id = b.author_id
    WHERE b.published`;
}
EOF
cat > resources/book.command.ts <<'EOF'
const isNameless = (name) => name === null || name === undefined || String(name).trim() === "";

function findAuthor(ctx, authorId) {
  const [author] = ctx.db.query(ctx.sql`SELECT id, name FROM author WHERE id = ${authorId}`);
  if (!author) {
    ctx.reject({ message: `author ${authorId} does not exist`, pointer: "/author_id", hint: "Use the id of an existing author.", status: 422 });
  }
  return author;
}

export function create(input, ctx) {
  const published = input.published ?? false;
  const author = findAuthor(ctx, input.author_id);
  if (published && isNameless(author.name)) {
    ctx.reject({ message: "a book whose author has no name cannot be published", pointer: "/published", hint: "Give the author a name, or create the book unpublished.", status: 422 });
  }
  const [row] = ctx.db.query(ctx.sql`INSERT INTO book (title, author_id, published) VALUES (${input.title}, ${input.author_id}, ${published}) RETURNING id`);
  return row.id;
}

export function update(input, ctx) {
  if ("published" in input || "author_id" in input) {
    const authorId = "author_id" in input ? input.author_id : ctx.db.query(ctx.sql`SELECT author_id FROM book WHERE id = ${ctx.id}`)[0].author_id;
    const author = findAuthor(ctx, authorId);
    const published = input.published ?? true;
    if (published && isNameless(author.name)) {
      ctx.reject({ message: "a book whose author has no name cannot be published", pointer: "/published", hint: "Give the author a name, or unpublish the book.", status: 422 });
    }
  }
  if ("title" in input) ctx.db.exec(ctx.sql`UPDATE book SET title = ${input.title} WHERE id = ${ctx.id}`);
  if ("author_id" in input) ctx.db.exec(ctx.sql`UPDATE book SET author_id = ${input.author_id} WHERE id = ${ctx.id}`);
  if ("published" in input) ctx.db.exec(ctx.sql`UPDATE book SET published = ${input.published} WHERE id = ${ctx.id}`);
}

export function remove(input, ctx) {
  ctx.db.exec(ctx.sql`DELETE FROM book WHERE id = ${ctx.id}`);
}
EOF
cat > resources/Quote.json <<'EOF'
{
  "name": "Quote",
  "path": "/quotes",
  "query": "quote.query.ts",
  "itemsPerPage": 2,
  "allow": {"fetch": ["127.0.0.1:18090"]},
  "properties": {
    "id": {"type": "integer", "identifier": true},
    "text": {"type": "string"},
    "author": {"type": "string", "filterable": true}
  }
}
EOF
cat > resources/quote.query.ts <<'EOF'
export default async function query(ctx: QueryContext) {
  const res = await ctx.fetch("http://127.0.0.1:18090/quotes.json");
  let rows = (await res.json())
    .map((q) => ({ id: q.id, text: q.quote, author: q.by }))
    .sort((a, b) => a.id - b.id);
  if (ctx.operation === "item") return rows.find((r) => r.id === ctx.id) ?? null;
  if (ctx.filters.author !== undefined) rows = rows.filter((r) => r.author === ctx.filters.author);
  const start = (ctx.page - 1) * ctx.itemsPerPage;
  return { items: rows.slice(start, start + ctx.itemsPerPage), totalItems: rows.length };
}
EOF
cat > resources/AuthorReport.json <<'EOF'
{
  "name": "AuthorReport",
  "operations": [
    {"method": "GET", "path": "/business/export", "format": "csv", "query": "author_report.query.ts"}
  ],
  "properties": {
    "author": {"type": "string"},
    "published_books": {"type": "integer"}
  }
}
EOF
cat > resources/author_report.query.ts <<'EOF'
export default function query(ctx: QueryContext): Sql {
  return ctx.sql`
    SELECT a.name AS author, count(b.id) AS published_books
    FROM author a
    LEFT JOIN book b ON b.author_id = a.id AND b.published
    WHERE a.name IS NOT NULL AND a.name <> ''
    GROUP BY a.id, a.name
    ORDER BY a.name, a.id`;
}
EOF
./caddy resource validate --dir resources --dsn 'postgres://eval_rw:eval_rw@postgres:5432/llmapi_eval'; echo "exit=$?"

